function resetAdventure(){Object.assign(state,{stars:0,starBank:0,height:0,verticalSpeed:0,flightTime:0,flightEnergy:100,jumpCooldown:0,spinTime:0,obstaclesHit:0,jumps:0,flights:0});for(const item of starItems){item.collectedLap=-1;item.mesh.visible=true;}for(const item of obstacleItems){item.hitLap=-1;item.mesh.visible=true;}adventureGroup.visible=true;player.userData.wings.visible=false;}
function convertStars(){while(state.starBank>=8&&state.boost<2){state.starBank-=8;state.boost++;notify('별 8개 → 부스터 +1',1.2);tone(900,.12);}}
function jump(){if(state.mode!=='race'||state.height>.05||state.flightTime>0||state.jumpCooldown>0)return;state.verticalSpeed=9.5;state.height=.06;state.jumpCooldown=.9;state.jumps++;tone(500,.1);}
function fly(){if(state.mode!=='race')return;if(state.flightTime>0){state.flightTime=0;state.verticalSpeed=0;notify('착륙합니다',.7);return;}if(state.flightEnergy<100){notify('비행 에너지 충전 중',1);return;}state.flightEnergy=0;state.flightTime=5;state.verticalSpeed=0;state.flights++;notify('FLIGHT MODE · 5초',1.2);tone(980,.2);}
function updateAdventure(dt,previousProgress){state.jumpCooldown=Math.max(0,state.jumpCooldown-dt);state.spinTime=Math.max(0,state.spinTime-dt);
 if(state.flightTime>0){state.flightTime=Math.max(0,state.flightTime-dt);state.height=lerp(state.height,4.5,1-Math.exp(-dt*5));state.verticalSpeed=0;}else{if(state.height>0||state.verticalSpeed>0){state.verticalSpeed-=20*dt;state.height=Math.max(0,state.height+state.verticalSpeed*dt);if(state.height===0)state.verticalSpeed=0;}if(state.height===0)state.flightEnergy=Math.min(100,state.flightEnergy+8*dt);}
 player.userData.wings.visible=state.flightTime>0;const lap=Math.floor(state.progress/trackLength),local=state.progress%trackLength;
 for(const item of starItems){item.mesh.visible=item.collectedLap!==lap;item.mesh.rotation.y=state.time*1.8+item.s;item.mesh.position.y=pointAt(item.s).y+item.height+Math.sin(state.time*3+item.s)*.15;
 const gap=Math.abs(item.s-local);if(item.collectedLap!==lap&&gap<2.1&&Math.abs(item.lateral-state.lateral)<1.45&&Math.abs(item.height-(state.height+1.0))<1.45){item.collectedLap=lap;item.mesh.visible=false;state.stars++;state.starBank++;tone(700+(state.stars%5)*80,.045);convertStars();}}
 for(const item of obstacleItems){const gap=Math.abs(item.s-local);if(item.hitLap===lap||gap>2.0||Math.abs(item.lateral-state.lateral)>1.35||state.height>item.height+.15)continue;item.hitLap=lap;if(state.collision>0)continue;state.obstaclesHit++;state.collision=1.0;state.speed*=item.kind==='crate'?.48:.62;state.boostTime=0;if(item.kind==='banana'||item.kind==='oil')state.spinTime=1.0;notify(({banana:'바나나! 미끄러짐',crate:'상자 충돌!',oil:'기름 웅덩이!',cone:'콘 충돌!',zombie:'좀비와 충돌!'})[item.kind]+' · Space로 점프',1.0);tone(140,.18);}
}
function adventureHUD(){$('star-count').textContent=state.stars||0;$('star-bank').textContent=(state.starBank||0)+' / 8';$('flight-meter').style.width=(state.flightTime>0?state.flightTime/5*100:state.flightEnergy||0)+'%';$('flight-label').textContent=state.flightTime>0?'비행 중 '+state.flightTime.toFixed(1)+'s':state.flightEnergy>=100?'F · 비행 준비 완료':'비행 충전 '+Math.floor(state.flightEnergy||0)+'%';$('air-label').textContent=state.flightTime>0?'FLIGHT':state.height>.05?'JUMP':'';$('jump-btn').disabled=state.mode!=='race'||state.height>.05||state.jumpCooldown>0;$('flight-btn').disabled=state.mode!=='race'||(state.flightTime<=0&&state.flightEnergy<100);}

