function updateHUD(){adventureHUD();$('speed').textContent=Math.round(state.speed*4.5);$('speed-bar').style.width=clamp(state.speed/64*100,0,100)+'%';$('position').innerHTML=rank()+'<span>/ 4</span>';$('lap').textContent=Math.min(3,Math.floor(state.progress/trackLength)+1);$('time').textContent=formatTime(state.time);$('gauge-fill').style.width=clamp(state.gauge,0,100)+'%';$('boost1').classList.toggle('ready',state.boost>0);$('boost2').classList.toggle('ready',state.boost>1);$('boost-label').textContent=state.boostTime>0?'BOOST ACTIVE':state.boost>0?'Ctrl 키로 부스터 사용':state.driftHeld?'DRIFT · 충전 중':'별 8개 또는 드리프트 → 부스터';const ranks=[{name:'나',progress:state.progress},...ai].sort((a,b)=>b.progress-a.progress);$('rank-list').innerHTML=ranks.map((r,i)=>`<div class="${r.name==='나'?'me':''}">${i+1}　${r.name}</div>`).join('');drawMap();}
function updateCamera(dt,instant=false){const {p,t,n}=poseAt(state.progress,state.lateral);const target=p.clone().addScaledVector(t,-9.3).add(new THREE.Vector3(0,5.3+(state.height||0)*.8,0));const look=poseAt(state.progress+10,state.lateral).p.add(new THREE.Vector3(0,1+(state.height||0)*.8,0));camera.position.lerp(target,instant?1:1-Math.exp(-dt*8));camera.lookAt(look);camera.fov=lerp(camera.fov,state.boostTime>0?67:53+state.speed*.12,Math.min(1,dt*4));camera.updateProjectionMatrix();sun.position.copy(p).add(new THREE.Vector3(-45,75,-20));sun.target.position.copy(p);sun.target.updateMatrixWorld();rimLight.position.copy(p).add(new THREE.Vector3(8,5,-6));rimLight.target.position.copy(p);fillLight.position.copy(p).add(new THREE.Vector3(3,5,10));fillLight.target.position.copy(p);}
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}addEventListener('resize',resize);resize();
let last=0,uiTimer=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000||.016,.25);last=now;if(state.mode==='garage'){const mobile=innerWidth<600;const shift=innerWidth<900?2.5:3;displayKart.rotation.y=Math.sin(now*.00025)*.25+.45;camera.position.set(7.5,4.9,10.5);camera.lookAt(mobile?new THREE.Vector3(0,-1.1,0):new THREE.Vector3(shift,1.2,-.5));camera.fov=mobile?49:45;camera.updateProjectionMatrix();sun.position.set(-10,14,10);rimLight.position.set(7,5,-6);rimLight.target.position.set(0,1,0);fillLight.position.set(3,4,10);fillLight.target.position.set(0,1,0);sun.target.position.set(0,0,0);}else if(state.mode==='countdown'){state.count-=dt;const signal=Math.max(0,Math.ceil(state.count));if(signal!==state.countdownSignal){tone(signal>0?440:880,.16);state.countdownSignal=signal;}$('countdown').textContent=signal||'GO!';$('start-lights').querySelectorAll('i').forEach((light,i)=>light.classList.toggle('on',i>=signal-1));if(state.count<=0){state.mode='race';state.goTime=.8;$('start-lights').classList.add('go');oldRank=rank();}updateCamera(dt);}else if(state.mode==='race'){let remaining=dt;while(remaining>0&&state.mode==='race'){const step=Math.min(remaining,1/60);updatePhysics(step);remaining-=step;}if(state.mode==='race')updateCamera(dt);if(state.goTime>0){state.goTime-=dt;if(state.goTime<=0){show('countdown',false);show('start-lights',false);}}}
updateEngine();updateMusic();
if(state.mode!=='paused'){if(state.noticeTime>0){state.noticeTime-=dt;if(state.noticeTime<=0)$('notice').textContent=''}trailPool.forEach(m=>{if(m.userData.life>0){m.userData.life-=dt;m.material.opacity=Math.max(0,m.userData.life/2.3*.38);m.visible=state.mode!=='garage'&&m.userData.life>0}})}uiTimer+=dt;if(state.mode!=='garage'&&uiTimer>.065){updateHUD();uiTimer=0;}renderer.render(scene,camera);}
show('loading',false);show('garage',true);updateSelection();requestAnimationFrame(frame);
// The optional browser tool uses exactly the same selection and start actions as the UI.
const context=document.modelContext;if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'configure_race',title:'레이스 준비',description:'차고에서 캐릭터, 카트, 트랙을 선택합니다. 경기를 시작하지 않습니다.',inputSchema:{type:'object',properties:{character:{type:'integer',enum:[0,1,2,3]},kart:{type:'integer',enum:[0,1,2,3,4,5]},track:{type:'integer',enum:[0,1,2,3]}},required:['character','kart','track'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(state.mode!=='garage')throw Error('먼저 차고로 돌아가세요');if(!input||Object.keys(input).length!==3||!['character','kart','track'].every(k=>Number.isInteger(input[k])&&(k==='track'?[0,1,2,3]:k==='character'?[0,1,2,3]:[0,1,2,3,4,5]).includes(input[k])))throw Error('캐릭터는 0~3, 카트는 0~5, 트랙은 0~3이어야 합니다');Object.assign(selection,input);updateSelection();return {...selection,mode:state.mode};}})).catch(()=>{});}catch{}}
