window.pocketKart={getState:()=>({...state,selection:{...selection},trackLength,theme:THEMES[selection.track].kind,itemCounts:{stars:starItems.length,obstacles:obstacleItems.length},ai:ai.map(a=>({progress:a.progress,finishTime:a.finishTime}))})};

